// stlport
//
// The DebugCommandMap block. It reads the entry name and throws it away, parses
// a full entry into a local, and then discards that too -- so in a release build
// the block validates its own syntax and stores nothing. The retail code really
// is this: getNextToken with the result unused, initFromINI into stack space,
// and two UnicodeString destructors on the way out.
//
// Field names and offsets are the retail table at VA 0x00BDAD98
// Nothing writes 0x00-0x07, so that stays a pad. The complete table is owned
// by MessageStream/MetaEvent.cpp; both callbacks refer to the same native datum.
//
// The class views below are MetaEvent.cpp's (the approved TU this body belongs
// to), so this file composes into it.
#include "unicode_string.h"

typedef int Int;

class INI
{
public:
	const char *getNextToken(const char *seps);
	void initFromINI(void *instance, const struct FieldParse *table);
};

typedef void (*FieldParseProc)(class INI *, void *, void *, const void *);

struct FieldParse { const char *token; FieldParseProc parse; const void *userData; int offset; };

class GameMessage
{
public:
	enum Type { MSG_INVALID = 0 };
};

// The local is retail's MetaMapRec (no vptr in BFME 2): its destructor is the
// rowed ??1MetaMapRec at 0x001DB48E (MessageStream/MetaEvent.cpp), so it is
// declared, never defined here. Its field table is the DebugCommandMapEntry one.
class MetaMapRec
{
public:
	MetaMapRec *m_next;					// 0x00  no INI field writes here
public:
	GameMessage::Type m_meta;			// 0x04
public:
	int m_key;							// 0x08  Key
public:
	int m_transition;					// 0x0c  Transition
public:
	Int m_modState;						// 0x10  Modifiers
public:
	Int m_usableIn;						// 0x14  UseableIn
public:
	Int m_category;						// 0x18  Category
public:
	UnicodeString m_description;		// 0x1c  Description
public:
	UnicodeString m_displayName;		// 0x20  DisplayName
public:
	~MetaMapRec();
};

struct DebugCommandMapEntry
{
    static const FieldParse m_fieldParseTable[8];
};

void parseDebugCommandMap( INI *ini )
{
	ini->getNextToken( 0 );

	MetaMapRec entry;
	ini->initFromINI( &entry, DebugCommandMapEntry::m_fieldParseTable );
}
